# -*- coding: utf-8 -*-
"""
Projects-card announcement -> one Outlook draft (the approved version: the whole design as
one picture, so it looks exactly the same for everyone). Nothing is ever sent.

    python make_projects_draft_picture.py

Needs Windows + Outlook desktop, and once:  pip install pywin32
The draft is saved quietly in Drafts with the real subject. Pictures go in as hidden
inline images, so they never show as attachments.
"""
import base64
import os
import sys
import tempfile

SUBJECT = 'إطلاق النسخة المؤتمتة من متابعة تحديث بطاقات المشاريع'

IMAGES = {
    "pc_full": '',
}

VERSIONS = {
    4: '<!DOCTYPE html>\n<html lang="ar" dir="rtl" xmlns:v="urn:schemas-microsoft-com:vml" xmlns:o="urn:schemas-microsoft-com:office:office">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<meta name="x-apple-disable-message-reformatting">\n<meta name="color-scheme" content="light only">\n<meta name="supported-color-schemes" content="light only">\n<title>إطلاق النسخة المؤتمتة من متابعة تحديث بطاقات المشاريع</title>\n<!--[if mso]>\n<xml><o:OfficeDocumentSettings><o:AllowPNG/><o:PixelsPerInch>96</o:PixelsPerInch></o:OfficeDocumentSettings></xml>\n<style>\ntable {border-collapse:collapse; mso-table-lspace:0pt; mso-table-rspace:0pt;}\ntd, b {font-family:\'Segoe UI\', Tahoma, sans-serif; mso-bidi-font-family:\'Segoe UI\';}\nimg {-ms-interpolation-mode:bicubic;}\n</style>\n<![endif]-->\n<style>\n:root {color-scheme: light only;}\nbody {margin:0 !important; padding:0 !important; -webkit-text-size-adjust:100%;}\nimg {border:0; outline:none; text-decoration:none; display:block;}\n@media screen and (max-width:620px) { .card {width:100% !important;} .fluid {width:100% !important; height:auto !important;} }\n</style>\n</head>\n<body dir="rtl" bgcolor="#DCE1E9" style="margin:0;padding:0;background:#DCE1E9">\n<table role="presentation" dir="ltr" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#DCE1E9" style="background:#DCE1E9">\n<tr><td align="center" style="padding:24px 10px">\n<!--[if mso]><table role="presentation" dir="ltr" width="600" cellpadding="0" cellspacing="0" border="0" align="center"><tr><td><![endif]-->\n<table role="presentation" class="card" dir="ltr" width="600" cellpadding="0" cellspacing="0" border="0" align="center" style="width:600px;border-collapse:collapse">\n<tr><td><img class="fluid" src="cid:pc_full" width="600" height="860" alt="إطلاق النسخة المؤتمتة من متابعة تحديث بطاقات المشاريع - السلام عليكم ورحمة الله وبركاته، - ضمن جهود إدارة أداء رأس المال البشري وضمان الجودة في تطوير آليات العمل ورفع كفاءة الأداء التشغيلي، يسرّنا إشعاركم بإطلاق النسخة المؤتمتة لمتابعة تحديث بطاقات المشاريع، وذلك اعتباراً من يوم الخميس الموافق ٢٦ نوفمبر ٢٠٢٦م. - وستكون المتابعة عبر سلسلة مراسلات واحدة تصلكم من البريد الإلكتروني للإدارة <span dir=\'ltr\' lang=\'en\' style=\'direction:ltr;unicode-bidi:embed;white-space:nowrap\'>HC Performance</span>&#x200F;، لذا نأمل أن يكون تحديثكم ضمن هذه السلسلة بالرد على الرسالة ذاتها عبر خيار <b>الرد على الكل</b>، وتجنّب إرسال رسائل مستقلة. - وتهدف هذه الخطوة إلى تعزيز كفاءة متابعة المشاريع، ورفع مستوى الالتزام بتحديثها بشكل مستمر، بما يسهم في تحسين جودة البيانات، وتسهيل متابعة تنفيذها وفق الخطط المعتمدة. - شاكرين لكم تعاونكم المستمر، ونتطلع إلى مواصلة العمل معاً بما يسهم في تحقيق مستهدفات الوكالة. - وتقبلوا خالص التحية والتقدير، - إدارة أداء رأس المال البشري وضمان الجودة" style="display:block;width:600px;height:860px;border:0" border="0"></td></tr>\n</table>\n<!--[if mso]></td></tr></table><![endif]-->\n</td></tr>\n</table>\n</body>\n</html>',
}

# MAPI properties for inline (CID) pictures
PR_ATTACH_CONTENT_ID = "http://schemas.microsoft.com/mapi/proptag/0x3712001F"
PR_ATTACH_MIME_TAG = "http://schemas.microsoft.com/mapi/proptag/0x370E001F"
PR_ATTACHMENT_HIDDEN = "http://schemas.microsoft.com/mapi/proptag/0x7FFE000B"


def make_draft(outlook, number, subject):
    html = VERSIONS[number]
    mail = outlook.CreateItem(0)          # 0 = mail item
    mail.BodyFormat = 2                   # 2 = HTML
    mail.Subject = subject

    temp_files = []
    try:
        for cid, data in IMAGES.items():
            if "cid:" + cid not in html:
                continue
            path = os.path.join(tempfile.gettempdir(), cid + ".png")
            with open(path, "wb") as f:
                f.write(base64.b64decode(data))
            temp_files.append(path)
            att = mail.Attachments.Add(path, 1, 0)   # by value, inline
            pa = att.PropertyAccessor
            pa.SetProperty(PR_ATTACH_CONTENT_ID, cid)
            pa.SetProperty(PR_ATTACH_MIME_TAG, "image/png")
            pa.SetProperty(PR_ATTACHMENT_HIDDEN, True)
        mail.HTMLBody = html
        mail.Save()                       # goes to Drafts; no window opens
    finally:
        for path in temp_files:
            try:
                os.remove(path)
            except OSError:
                pass


def main():
    try:
        import win32com.client
    except ImportError:
        print("Install the Outlook bridge first:  pip install pywin32")
        return
    outlook = win32com.client.Dispatch("Outlook.Application")
    make_draft(outlook, 4, SUBJECT)
    print("Saved the announcement in Drafts. Open it, add recipients, and send.")


if __name__ == "__main__":
    main()
